{"command":"cat <<'EOF' > /tmp/test_wait4.rs
use std::process::Command;
use std::time::Instant;

fn main() {
    let start = Instant::now();
    let mut child = Command::new("sh")
        .arg("-c")
        .arg("sleep 0.1")
        .spawn()
        .unwrap();

    let pid = child.id() as i32;
    let mut status: libc::c_int = 0;
    let mut rusage: libc::rusage = unsafe { std::mem::zeroed() };

    let res = unsafe { libc::wait4(pid, &mut status, 0, &mut rusage) };
    let elapsed = start.elapsed().as_secs_f64();

    println!("wait4 res: {}", res);
    println!("status: {}", status);
    println!("elapsed: {} s", elapsed);
    let user = rusage.ru_utime.tv_sec as f64 + rusage.ru_utime.tv_usec as f64 * 1e-6;
    let sys = rusage.ru_stime.tv_sec as f64 + rusage.ru_stime.tv_usec as f64 * 1e-6;
    let rss = rusage.ru_maxrss as u64 * 1024;
    println!("user: {} s, sys: {} s, rss: {} bytes", user, sys, rss);
}
EOF
