use std::path::PathBuf;
use std::process;

#[derive(Debug, Clone)]
pub struct ParameterScanOpts {
    pub var: String,
    pub min: String,
    pub max: String,
}

#[derive(Debug, Clone)]
pub struct ParameterListOpts {
    pub var: String,
    pub values: Vec<String>,
}

#[derive(Debug, Clone, PartialEq)]
pub enum IgnoreFailure {
    None,
    All,
    Specific(Vec<i32>),
}

#[derive(Debug, Clone)]
pub struct Opts {
    pub warmup: u64,
    pub min_runs: u64,
    pub max_runs: Option<u64>,
    pub runs: Option<u64>,
    pub setup: Option<String>,
    pub reference: Option<String>,
    pub reference_name: Option<String>,
    pub prepare: Vec<String>,
    pub conclude: Vec<String>,
    pub cleanup: Option<String>,
    pub parameter_scan: Option<ParameterScanOpts>,
    pub parameter_step_size: Option<String>,
    pub parameter_list: Vec<ParameterListOpts>,
    pub shell: Option<String>,
    pub shell_none: bool,
    pub ignore_failure: IgnoreFailure,
    pub style: String,
    pub sort: String,
    pub time_unit: Option<String>,
    pub export_asciidoc: Option<PathBuf>,
    pub export_csv: Option<PathBuf>,
    pub export_json: Option<PathBuf>,
    pub export_markdown: Option<PathBuf>,
    pub export_orgmode: Option<PathBuf>,
    pub show_output: bool,
    pub output: Vec<String>,
    pub input: Option<String>,
    pub command_names: Vec<String>,
    pub commands: Vec<String>,
}

pub fn parse_args() -> Opts {
    let raw_args: Vec<String> = std::env::args().collect();
    let bin_name = raw_args.get(0).map(|s| s.as_str()).unwrap_or("executable");

    // Check for --help or -h
    if raw_args.iter().any(|a| a == "-h" || a == "--help") {
        print_help();
        process::exit(0);
    }

    // Check for --version or -V
    if raw_args.iter().any(|a| a == "-V" || a == "--version") {
        println!("hyperfine 1.20.0");
        process::exit(0);
    }

    let mut warmup: u64 = 0;
    let mut min_runs: Option<u64> = None;
    let mut max_runs: Option<u64> = None;
    let mut runs: Option<u64> = None;
    let mut setup: Option<String> = None;
    let mut reference: Option<String> = None;
    let mut reference_name: Option<String> = None;
    let mut prepare: Vec<String> = Vec::new();
    let mut conclude: Vec<String> = Vec::new();
    let mut cleanup: Option<String> = None;
    let mut parameter_scan: Option<ParameterScanOpts> = None;
    let mut parameter_step_size: Option<String> = None;
    let mut parameter_list: Vec<ParameterListOpts> = Vec::new();
    let mut shell: Option<String> = None;
    let mut shell_none = false;
    let mut ignore_failure = IgnoreFailure::None;
    let mut style: Option<String> = None;
    let mut sort: Option<String> = None;
    let mut time_unit: Option<String> = None;
    let mut export_asciidoc: Option<PathBuf> = None;
    let mut export_csv: Option<PathBuf> = None;
    let mut export_json: Option<PathBuf> = None;
    let mut export_markdown: Option<PathBuf> = None;
    let mut export_orgmode: Option<PathBuf> = None;
    let mut show_output = false;
    let mut output: Vec<String> = Vec::new();
    let mut input: Option<String> = None;
    let mut command_names: Vec<String> = Vec::new();
    let mut commands: Vec<String> = Vec::new();

    // Track explicit argument occurrences for conflict detection
    let mut has_runs = false;
    let mut has_min_runs = false;
    let mut has_max_runs = false;
    let mut has_param_scan = false;
    let mut has_param_list = false;
    let mut has_param_step = false;
    let mut has_style = false;
    let mut has_show_output = false;
    let mut has_shell = false;
    let mut has_shell_none = false;
    let mut has_output = false;
    let mut has_setup = false;
    let mut has_cleanup = false;
    let mut has_input = false;

    let mut i = 1;
    let mut parsing_flags = true;

    while i < raw_args.len() {
        let arg = &raw_args[i];

        if parsing_flags && arg == "--" {
            parsing_flags = false;
            i += 1;
            continue;
        }

        if parsing_flags && arg.starts_with('-') && arg != "-" {
            // Check for key=value
            let (flag, inline_val) = if let Some(pos) = arg.find('=') {
                (&arg[..pos], Some(&arg[pos + 1..]))
            } else {
                (arg.as_str(), None)
            };

            match flag {
                "-w" | "--warmup" => {
                    let val = get_val(&raw_args, &mut i, inline_val, flag);
                    warmup = parse_u64(flag, &val);
                }
                "-m" | "--min-runs" => {
                    has_min_runs = true;
                    let val = get_val(&raw_args, &mut i, inline_val, flag);
                    min_runs = Some(parse_u64(flag, &val));
                }
                "-M" | "--max-runs" => {
                    has_max_runs = true;
                    let val = get_val(&raw_args, &mut i, inline_val, flag);
                    max_runs = Some(parse_u64(flag, &val));
                }
                "-r" | "--runs" => {
                    has_runs = true;
                    let val = get_val(&raw_args, &mut i, inline_val, flag);
                    runs = Some(parse_u64(flag, &val));
                }
                "-s" | "--setup" => {
                    if has_setup {
                        clap_error(&format!("the argument '--setup <CMD>' cannot be used multiple times"));
                    }
                    has_setup = true;
                    let val = get_val(&raw_args, &mut i, inline_val, flag);
                    setup = Some(val);
                }
                "--reference" => {
                    let val = get_val(&raw_args, &mut i, inline_val, flag);
                    reference = Some(val);
                }
                "--reference-name" => {
                    let val = get_val(&raw_args, &mut i, inline_val, flag);
                    reference_name = Some(val);
                }
                "-p" | "--prepare" => {
                    let val = get_val(&raw_args, &mut i, inline_val, flag);
                    prepare.push(val);
                }
                "-C" | "--conclude" => {
                    let val = get_val(&raw_args, &mut i, inline_val, flag);
                    conclude.push(val);
                }
                "-c" | "--cleanup" => {
                    if has_cleanup {
                        clap_error(&format!("the argument '--cleanup <CMD>' cannot be used multiple times"));
                    }
                    has_cleanup = true;
                    let val = get_val(&raw_args, &mut i, inline_val, flag);
                    cleanup = Some(val);
                }
                "-P" | "--parameter-scan" => {
                    has_param_scan = true;
                    let var = if let Some(v) = inline_val {
                        v.to_string()
                    } else {
                        i += 1;
                        if i >= raw_args.len() {
                            clap_error("the argument '--parameter-scan <VAR> <MIN> <MAX>' requires 3 values");
                        }
                        raw_args[i].clone()
                    };
                    i += 1;
                    if i >= raw_args.len() {
                        clap_error("the argument '--parameter-scan <VAR> <MIN> <MAX>' requires 3 values");
                    }
                    let min = raw_args[i].clone();
                    i += 1;
                    if i >= raw_args.len() {
                        clap_error("the argument '--parameter-scan <VAR> <MIN> <MAX>' requires 3 values");
                    }
                    let max = raw_args[i].clone();
                    parameter_scan = Some(ParameterScanOpts { var, min, max });
                }
                "-D" | "--parameter-step-size" => {
                    has_param_step = true;
                    let val = get_val(&raw_args, &mut i, inline_val, flag);
                    parameter_step_size = Some(val);
                }
                "-L" | "--parameter-list" => {
                    has_param_list = true;
                    let var = if let Some(v) = inline_val {
                        v.to_string()
                    } else {
                        i += 1;
                        if i >= raw_args.len() {
                            clap_error("the argument '--parameter-list <VAR> <VALUES>' requires 2 values");
                        }
                        raw_args[i].clone()
                    };
                    i += 1;
                    if i >= raw_args.len() {
                        clap_error("the argument '--parameter-list <VAR> <VALUES>' requires 2 values");
                    }
                    let values_raw = raw_args[i].clone();
                    let values: Vec<String> = values_raw.split(',').map(|s| s.to_string()).collect();
                    parameter_list.push(ParameterListOpts { var, values });
                }
                "-S" | "--shell" => {
                    has_shell = true;
                    let val = get_val(&raw_args, &mut i, inline_val, flag);
                    shell = Some(val);
                }
                "-N" => {
                    has_shell_none = true;
                    shell_none = true;
                }
                "-i" | "--ignore-failure" => {
                    if let Some(v) = inline_val {
                        if v.is_empty() || v == "all-non-zero" {
                            ignore_failure = IgnoreFailure::All;
                        } else {
                            let mut codes = Vec::new();
                            for part in v.split(',') {
                                match part.trim().parse::<i32>() {
                                    Ok(code) => codes.push(code),
                                    Err(_) => {
                                        eprintln!("Error: Could not read numeric integer argument to '--ignore-failure': invalid digit found in string");
                                        process::exit(1);
                                    }
                                }
                            }
                            ignore_failure = IgnoreFailure::Specific(codes);
                        }
                    } else {
                        ignore_failure = IgnoreFailure::All;
                    }
                }
                "--style" => {
                    has_style = true;
                    let val = get_val(&raw_args, &mut i, inline_val, flag);
                    if !["auto", "basic", "full", "nocolor", "color", "none"].contains(&val.as_str()) {
                        clap_error(&format!("invalid value '{}' for '--style <TYPE>'\n  [possible values: auto, basic, full, nocolor, color, none]", val));
                    }
                    style = Some(val);
                }
                "--sort" => {
                    let val = get_val(&raw_args, &mut i, inline_val, flag);
                    if !["auto", "command", "mean-time"].contains(&val.as_str()) {
                        clap_error(&format!("invalid value '{}' for '--sort <METHOD>'\n  [possible values: auto, command, mean-time]", val));
                    }
                    sort = Some(val);
                }
                "-u" | "--time-unit" => {
                    let val = get_val(&raw_args, &mut i, inline_val, flag);
                    if !["microsecond", "millisecond", "second"].contains(&val.as_str()) {
                        clap_error(&format!("invalid value '{}' for '--time-unit <UNIT>'\n  [possible values: microsecond, millisecond, second]", val));
                    }
                    time_unit = Some(val);
                }
                "--export-asciidoc" => {
                    let val = get_val(&raw_args, &mut i, inline_val, flag);
                    export_asciidoc = Some(PathBuf::from(val));
                }
                "--export-csv" => {
                    let val = get_val(&raw_args, &mut i, inline_val, flag);
                    export_csv = Some(PathBuf::from(val));
                }
                "--export-json" => {
                    let val = get_val(&raw_args, &mut i, inline_val, flag);
                    export_json = Some(PathBuf::from(val));
                }
                "--export-markdown" => {
                    let val = get_val(&raw_args, &mut i, inline_val, flag);
                    export_markdown = Some(PathBuf::from(val));
                }
                "--export-orgmode" => {
                    let val = get_val(&raw_args, &mut i, inline_val, flag);
                    export_orgmode = Some(PathBuf::from(val));
                }
                "--show-output" => {
                    has_show_output = true;
                    show_output = true;
                }
                "--output" => {
                    has_output = true;
                    let val = get_val(&raw_args, &mut i, inline_val, flag);
                    output.push(val);
                }
                "--input" => {
                    if has_input {
                        clap_error(&format!("the argument '--input <WHERE>' cannot be used multiple times"));
                    }
                    has_input = true;
                    let val = get_val(&raw_args, &mut i, inline_val, flag);
                    input = Some(val);
                }
                "-n" | "--command-name" => {
                    let val = get_val(&raw_args, &mut i, inline_val, flag);
                    command_names.push(val);
                }
                _ => {
                    clap_error(&format!("unexpected argument '{}' found\n\n  tip: to pass '{}' as a value, use '-- {}'", flag, flag, flag));
                }
            }
        } else {
            commands.push(arg.clone());
        }

        i += 1;
    }

    // Check conflicts and required dependencies
    if has_runs && has_min_runs {
        clap_error("the argument '--runs <NUM>' cannot be used with '--min-runs <NUM>'");
    }
    if has_runs && has_max_runs {
        clap_error("the argument '--runs <NUM>' cannot be used with '--max-runs <NUM>'");
    }
    if has_param_scan && has_param_list {
        clap_error("the argument '--parameter-scan <VAR> <MIN> <MAX>' cannot be used with '--parameter-list <VAR> <VALUES>'");
    }
    if has_param_step && !has_param_scan {
        clap_error_missing("--parameter-scan <VAR> <MIN> <MAX>");
    }
    if reference_name.is_some() && reference.is_none() {
        clap_error_missing("--reference <CMD>");
    }
    if has_style && has_show_output {
        clap_error("the argument '--style <TYPE>' cannot be used with '--show-output'");
    }
    if has_show_output && has_output {
        clap_error("the argument '--show-output' cannot be used with '--output <WHERE>'");
    }
    if has_shell_none && has_shell {
        clap_error("the argument '-N' cannot be used with '--shell <SHELL>'");
    }

    if commands.is_empty() && reference.is_none() {
        clap_error_missing("<command>...");
    }

    Opts {
        warmup,
        min_runs: min_runs.unwrap_or(10),
        max_runs,
        runs,
        setup,
        reference,
        reference_name,
        prepare,
        conclude,
        cleanup,
        parameter_scan,
        parameter_step_size,
        parameter_list,
        shell,
        shell_none,
        ignore_failure,
        style: style.unwrap_or_else(|| "auto".to_string()),
        sort: sort.unwrap_or_else(|| "auto".to_string()),
        time_unit,
        export_asciidoc,
        export_csv,
        export_json,
        export_markdown,
        export_orgmode,
        show_output,
        output,
        input,
        command_names,
        commands,
    }
}

fn get_val(args: &[String], idx: &mut usize, inline: Option<&str>, flag: &str) -> String {
    if let Some(v) = inline {
        v.to_string()
    } else {
        *idx += 1;
        if *idx >= args.len() {
            clap_error(&format!("a value is required for '{}' but none was supplied", flag));
        }
        args[*idx].clone()
    }
}

fn parse_u64(flag: &str, val: &str) -> u64 {
    val.parse::<u64>().unwrap_or_else(|_| {
        let flag_name = match flag {
            "-w" | "--warmup" => "--warmup",
            "-m" | "--min-runs" => "--min-runs",
            "-M" | "--max-runs" => "--max-runs",
            "-r" | "--runs" => "--runs",
            _ => flag,
        };
        eprintln!("Error: Could not read numeric integer argument to '{}': invalid digit found in string", flag_name);
        process::exit(1);
    })
}

fn clap_error(msg: &str) -> ! {
    eprintln!("error: {}\n\nUsage: executable [OPTIONS] <command>...\n\nFor more information, try '--help'.", msg);
    process::exit(2);
}

fn clap_error_missing(arg: &str) -> ! {
    eprintln!("error: the following required arguments were not provided:\n  {}\n\nUsage: executable [OPTIONS] <command>...\n\nFor more information, try '--help'.", arg);
    process::exit(2);
}

fn print_help() {
    print!(r#"A command-line benchmarking tool.

Usage: executable [OPTIONS] <command>...

Arguments:
  <command>...
          The command to benchmark. This can be the name of an executable, a
          command line like "grep -i todo" or a shell command like "sleep 0.5 &&
          echo test". The latter is only available if the shell is not
          explicitly disabled via '--shell=none'. If multiple commands are
          given, hyperfine will show a comparison of the respective runtimes.

Options:
  -w, --warmup <NUM>
          Perform NUM warmup runs before the actual benchmark. This can be used
          to fill (disk) caches for I/O-heavy programs.
  -m, --min-runs <NUM>
          Perform at least NUM runs for each command (default: 10).
  -M, --max-runs <NUM>
          Perform at most NUM runs for each command. By default, there is no
          limit.
  -r, --runs <NUM>
          Perform exactly NUM runs for each command. If this option is not
          specified, hyperfine automatically determines the number of runs.
  -s, --setup <CMD>
          Execute CMD before each set of timing runs. This is useful for
          compiling your software with the provided parameters, or to do any
          other work that should happen once before a series of benchmark runs,
          not every time as would happen with the --prepare option.
      --reference <CMD>
          The reference command for the relative comparison of results. If this
          is unset, results are compared with the fastest command as reference.
      --reference-name <CMD>
          Give a meaningful name to the reference command.
  -p, --prepare <CMD>
          Execute CMD before each timing run. This is useful for clearing disk
          caches, for example.
          The --prepare option can be specified once for all commands or
          multiple times, once for each command. In the latter case, each
          preparation command will be run prior to the corresponding benchmark
          command.
  -C, --conclude <CMD>
          Execute CMD after each timing run. This is useful for killing
          long-running processes started (e.g. a web server started in
          --prepare), for example.
          The --conclude option can be specified once for all commands or
          multiple times, once for each command. In the latter case, each
          conclude command will be run after the corresponding benchmark
          command.
  -c, --cleanup <CMD>
          Execute CMD after the completion of all benchmarking runs for each
          individual command to be benchmarked. This is useful if the commands
          to be benchmarked produce artifacts that need to be cleaned up.
  -P, --parameter-scan <VAR> <MIN> <MAX>
          Perform benchmark runs for each value in the range MIN..MAX. Replaces
          the string '{{VAR}}' in each command by the current parameter value.

            Example:  hyperfine -P threads 1 8 'make -j {{threads}}'

          This performs benchmarks for 'make -j 1', 'make -j 2', …, 'make -j 8'.

          To have the value increase following different patterns, use shell
          arithmetics.

            Example: hyperfine -P size 0 3 'sleep $((2**{{size}}))'

          This performs benchmarks with power of 2 increases: 'sleep 1', 'sleep
          2', 'sleep 4', …
          The exact syntax may vary depending on your shell and OS.
  -D, --parameter-step-size <DELTA>
          This argument requires --parameter-scan to be specified as well.
          Traverse the range MIN..MAX in steps of DELTA.

            Example:  hyperfine -P delay 0.3 0.7 -D 0.2 'sleep {{delay}}'

          This performs benchmarks for 'sleep 0.3', 'sleep 0.5' and 'sleep 0.7'.
  -L, --parameter-list <VAR> <VALUES>
          Perform benchmark runs for each value in the comma-separated list
          VALUES. Replaces the string '{{VAR}}' in each command by the current
          parameter value.

          Example:  hyperfine -L compiler gcc,clang '{{compiler}} -O2 main.cpp'

          This performs benchmarks for 'gcc -O2 main.cpp' and 'clang -O2
          main.cpp'.

          The option can be specified multiple times to run benchmarks for all
          possible parameter combinations.
  -S, --shell <SHELL>
          Set the shell to use for executing benchmarked commands. This can be
          the name or the path to the shell executable, or a full command line
          like "bash --norc". It can also be set to "default" to explicitly
          select the default shell on this platform. Finally, this can also be
          set to "none" to disable the shell. In this case, commands will be
          executed directly. They can still have arguments, but more complex
          things like "sleep 0.1; sleep 0.2" are not possible without a shell.
  -N
          An alias for '--shell=none'.
  -i, --ignore-failure[=<MODE>]
          Ignore failures of the benchmarked programs. Without a value or with
          'all-non-zero', all non-zero exit codes are ignored. You can also
          provide a comma-separated list of exit codes to ignore (e.g.,
          --ignore-failure=1,2).
      --style <TYPE>
          Set output style type (default: auto). Set this to 'basic' to disable
          output coloring and interactive elements. Set it to 'full' to enable
          all effects even if no interactive terminal was detected. Set this to
          'nocolor' to keep the interactive output without any colors. Set this
          to 'color' to keep the colors without any interactive output. Set this
          to 'none' to disable all the output of the tool.
      --sort <METHOD>
          Specify the sort order of the speed comparison summary and the
          exported tables for markup formats (Markdown, AsciiDoc, org-mode):
            * 'auto' (default): the speed comparison will be ordered by time and
              the markup tables will be ordered by command (input order).
            * 'command': order benchmarks in the way they were specified
            * 'mean-time': order benchmarks by mean runtime
  -u, --time-unit <UNIT>
          Set the time unit to be used. Possible values: microsecond,
          millisecond, second. If the option is not given, the time unit is
          determined automatically. This option affects the standard output as
          well as all export formats except for CSV and JSON.
      --export-asciidoc <FILE>
          Export the timing summary statistics as an AsciiDoc table to the given
          FILE. The output time unit can be changed using the --time-unit
          option.
      --export-csv <FILE>
          Export the timing summary statistics as CSV to the given FILE. If you
          need the timing results for each individual run, use the JSON export
          format. The output time unit is always seconds.
      --export-json <FILE>
          Export the timing summary statistics and timings of individual runs as
          JSON to the given FILE. The output time unit is always seconds
      --export-markdown <FILE>
          Export the timing summary statistics as a Markdown table to the given
          FILE. The output time unit can be changed using the --time-unit
          option.
      --export-orgmode <FILE>
          Export the timing summary statistics as an Emacs org-mode table to the
          given FILE. The output time unit can be changed using the --time-unit
          option.
      --show-output
          Print the stdout and stderr of the benchmark instead of suppressing
          it. This will increase the time it takes for benchmarks to run, so it
          should only be used for debugging purposes or when trying to benchmark
          output speed.
      --output <WHERE>
          Control where the output of the benchmark is redirected. Note that
          some programs like 'grep' detect when standard output is /dev/null and
          apply certain optimizations. To avoid that, consider using
          '--output=pipe'.

          <WHERE> can be:

            null:     Redirect output to /dev/null (the default).

            pipe:     Feed the output through a pipe before discarding it.

            inherit:  Don't redirect the output at all (same as
            '--show-output').

            <FILE>:   Write the output to the given file.

          This option can be specified once for all commands or multiple times,
          once for each command. Note: If you want to log the output of each and
          every iteration, you can use a shell redirection and the
          '$HYPERFINE_ITERATION' environment variable:
              hyperfine 'my-command > output-${HYPERFINE_ITERATION}.log'
      --input <WHERE>
          Control where the input of the benchmark comes from.

          <WHERE> can be:

            null:     Read from /dev/null (the default).

            <FILE>:   Read the input from the given file.
  -n, --command-name <NAME>
          Give a meaningful name to a command. This can be specified multiple
          times if several commands are benchmarked.
  -h, --help
          Print help
  -V, --version
          Print version
"#);
}
EOF"}

{"command":"cat <<'EOF' > src/parameter.rs
use std::process;
use crate::cli::{Opts, ParameterScanOpts, ParameterListOpts};

#[derive(Debug, Clone)]
pub struct ParameterSet {
    pub params: Vec<(String, String)>,
}

#[derive(Debug, Clone)]
pub struct BenchmarkTask {
    pub is_reference: bool,
    pub original_cmd: String,
    pub substituted_cmd: String,
    pub display_name: String,
    pub parameters: Vec<(String, String)>,
    pub setup: Option<String>,
    pub prepare: Option<String>,
    pub conclude: Option<String>,
    pub cleanup: Option<String>,
    pub output: Option<String>,
}

pub fn generate_tasks(opts: &Opts) -> Vec<BenchmarkTask> {
    let mut param_defs: Vec<(String, Vec<String>)> = Vec::new();

    if let Some(scan) = &opts.parameter_scan {
        let vals = generate_scan_values(scan, opts.parameter_step_size.as_deref());
        param_defs.push((scan.var.clone(), vals));
    } else if !opts.parameter_list.is_empty() {
        for list in &opts.parameter_list {
            param_defs.push((list.var.clone(), list.values.clone()));
        }
    }

    // Generate Cartesian product of parameter values
    let param_sets = generate_cartesian_product(&param_defs);

    let mut tasks = Vec::new();

    // First handle reference command if present
    if let Some(ref_cmd) = &opts.reference {
        let ref_name = opts.reference_name.as_ref().unwrap_or(ref_cmd);
        tasks.push(BenchmarkTask {
            is_reference: true,
            original_cmd: ref_cmd.clone(),
            substituted_cmd: ref_cmd.clone(),
            display_name: ref_name.clone(),
            parameters: Vec::new(),
            setup: opts.setup.clone(),
            prepare: None,  // Set later based on index/mapping
            conclude: None, // Set later based on index/mapping
            cleanup: opts.cleanup.clone(),
            output: None,   // Set later
        });
    }

    // Now handle benchmark commands for each parameter combination
    for p_set in &param_sets {
        for cmd in &opts.commands {
            let mut substituted_cmd = cmd.clone();
            for (var, val) in &p_set.params {
                substituted_cmd = substituted_cmd.replace(&format!("{{{}}}", var), val);
            }

            // Determine if there are parameters NOT present in original cmd template
            let mut unreplaced = Vec::new();
            for (var, val) in &p_set.params {
                if !cmd.contains(&format!("{{{}}}", var)) {
                    unreplaced.push(format!("{} = {}", var, val));
                }
            }

            let base_name = substituted_cmd.clone();
            let display_name = if unreplaced.is_empty() {
                base_name
            } else {
                format!("{} ({})", base_name, unreplaced.join(", "))
            };

            tasks.push(BenchmarkTask {
                is_reference: false,
                original_cmd: cmd.clone(),
                substituted_cmd,
                display_name,
                parameters: p_set.params.clone(),
                setup: substitute_params(opts.setup.as_deref(), &p_set.params),
                prepare: None,
                conclude: None,
                cleanup: substitute_params(opts.cleanup.as_deref(), &p_set.params),
                output: None,
            });
        }
    }

    // Apply -n / --command-name overrides if provided
    if !opts.command_names.is_empty() {
        let max_expected = tasks.len();
        if opts.command_names.len() > max_expected {
            eprintln!("Error: Too many --command-name options: Expected {} at most", max_expected);
            process::exit(1);
        }

        for (i, name_template) in opts.command_names.iter().enumerate() {
            if i < tasks.len() {
                let task = &mut tasks[i];
                let mut name = substitute_params(Some(name_template), &task.parameters).unwrap();

                // If there are parameters not present in original cmd template or name template, append suffix
                let mut unreplaced = Vec::new();
                for (var, val) in &task.parameters {
                    if !task.original_cmd.contains(&format!("{{{}}}", var)) && !name_template.contains(&format!("{{{}}}", var)) {
                        unreplaced.push(format!("{} = {}", var, val));
                    }
                }
                if !unreplaced.is_empty() {
                    name = format!("{} ({})", name, unreplaced.join(", "));
                }
                task.display_name = name;
            }
        }
    }

    // Apply --prepare options
    let total_tasks = tasks.len();
    if !opts.prepare.is_empty() {
        if opts.prepare.len() == 1 {
            let prep_template = &opts.prepare[0];
            for task in &mut tasks {
                task.prepare = substitute_params(Some(prep_template), &task.parameters);
            }
        } else if opts.prepare.len() == total_tasks {
            for (i, task) in tasks.iter_mut().enumerate() {
                task.prepare = substitute_params(Some(&opts.prepare[i]), &task.parameters);
            }
        } else {
            eprintln!("Error: The '--prepare' option has to be provided just once or N times, where N={} is the number of benchmark commands (including a potential reference).", total_tasks);
            process::exit(1);
        }
    }

    // Apply --conclude options
    if !opts.conclude.is_empty() {
        if opts.conclude.len() == 1 {
            let conc_template = &opts.conclude[0];
            for task in &mut tasks {
                task.conclude = substitute_params(Some(conc_template), &task.parameters);
            }
        } else if opts.conclude.len() == total_tasks {
            for (i, task) in tasks.iter_mut().enumerate() {
                task.conclude = substitute_params(Some(&opts.conclude[i]), &task.parameters);
            }
        } else {
            eprintln!("Error: The '--conclude' option has to be provided just once or N times, where N={} is the number of benchmark commands (including a potential reference).", total_tasks);
            process::exit(1);
        }
    }

    // Apply --output options
    if !opts.output.is_empty() {
        if opts.output.len() == 1 {
            let out = &opts.output[0];
            for task in &mut tasks {
                task.output = Some(out.clone());
            }
        } else if opts.output.len() == total_tasks {
            for (i, task) in tasks.iter_mut().enumerate() {
                task.output = Some(opts.output[i].clone());
            }
        } else {
            eprintln!("Error: The '--output' option has to be provided just once or N times, where N={} is the number of benchmark commands (including a potential reference).", total_tasks);
            process::exit(1);
        }
    }

    tasks
}

fn substitute_params(s: Option<&str>, params: &[(String, String)]) -> Option<String> {
    s.map(|template| {
        let mut res = template.to_string();
        for (var, val) in params {
            res = res.replace(&format!("{{{}}}", var), val);
        }
        res
    })
}

fn generate_scan_values(scan: &ParameterScanOpts, step_str: Option<&str>) -> Vec<String> {
    let min_val: f64 = scan.min.parse().unwrap_or_else(|_| {
        eprintln!("Error: Could not parse parameter scan min value");
        process::exit(1);
    });
    let max_val: f64 = scan.max.parse().unwrap_or_else(|_| {
        eprintln!("Error: Could not parse parameter scan max value");
        process::exit(1);
    });

    let step_str = step_str.unwrap_or("1");
    let step_val: f64 = step_str.parse().unwrap_or_else(|_| {
        eprintln!("Error: Could not parse parameter step size");
        process::exit(1);
    });

    if step_val == 0.0 {
        eprintln!("Error: Zero is not a valid parameter step");
        process::exit(1);
    }

    if min_val > max_val {
        eprintln!("Error: Empty parameter range");
        process::exit(1);
    }

    let precision = get_max_precision(&[&scan.min, &scan.max, step_str]);

    let mut values = Vec::new();
    let mut current = min_val;
    let eps = step_val.abs() * 1e-7;

    while current <= max_val + eps {
        if precision == 0 {
            values.push(format!("{}", current.round() as i64));
        } else {
            values.push(format!("{:.1$}", current, precision));
        }
        current += step_val;
    }

    if values.is_empty() {
        eprintln!("Error: Empty parameter range");
        process::exit(1);
    }

    values
}

fn get_max_precision(strs: &[&str]) -> usize {
    let mut max_p = 0;
    for s in strs {
        if let Some(pos) = s.find('.') {
            let p = s[pos + 1..].len();
            if p > max_p {
                max_p = p;
            }
        }
    }
    max_p
}

fn generate_cartesian_product(defs: &[(String, Vec<String>)]) -> Vec<ParameterSet> {
    if defs.is_empty() {
        return vec![ParameterSet { params: Vec::new() }];
    }

    // Outer loop is last def, inner loop is first def
    let mut result: Vec<Vec<(String, String)>> = vec![vec![]];

    for (var, values) in defs {
        let mut next_result = Vec::new();
        for val in values {
            for combo in &result {
                let mut new_combo = combo.clone();
                new_combo.push((var.clone(), val.clone()));
                next_result.push(new_combo);
            }
        }
        result = next_result;
    }

    result.into_iter().map(|params| ParameterSet { params }).collect()
}
EOF"}

