use std::fs::{File, OpenOptions};
use std::process::{Command, Stdio, process};
use std::time::Instant;
use crate::cli::{Opts, IgnoreFailure};
use crate::parameter::BenchmarkTask;

#[repr(C)]
#[derive(Copy, Clone)]
pub struct timeval {
    pub tv_sec: i64,
    pub tv_usec: i64,
}

#[repr(C)]
#[derive(Copy, Clone)]
pub struct rusage {
    pub ru_utime: timeval,
    pub ru_stime: timeval,
    pub ru_maxrss: i64,
    pub ru_ixrss: i64,
    pub ru_idrss: i64,
    pub ru_isrss: i64,
    pub ru_minflt: i64,
    pub ru_majflt: i64,
    pub ru_nswap: i64,
    pub ru_inblock: i64,
    pub ru_oublock: i64,
    pub ru_msgsnd: i64,
    pub ru_msgrcv: i64,
    pub ru_nsignals: i64,
    pub ru_nvcsw: i64,
    pub ru_nivcsw: i64,
}

extern "C" {
    pub fn wait4(pid: i32, status: *mut i32, options: i32, rusage: *mut rusage) -> i32;
}

#[derive(Debug, Clone)]
pub struct RunResult {
    pub time_sec: f64,
    pub user_sec: f64,
    pub system_sec: f64,
    pub max_rss_bytes: u64,
    pub exit_code: i32,
}

#[derive(Debug, Clone)]
pub struct ShellInfo {
    pub enabled: bool,
    pub cmd_parts: Vec<String>,
    pub mean_time: f64,
}

pub fn setup_shell(opts: &Opts) -> ShellInfo {
    if opts.shell_none {
        return ShellInfo {
            enabled: false,
            cmd_parts: Vec::new(),
            mean_time: 0.0,
        };
    }

    let shell_str = opts.shell.as_deref().unwrap_or("default");
    if shell_str == "none" {
        return ShellInfo {
            enabled: false,
            cmd_parts: Vec::new(),
            mean_time: 0.0,
        };
    }

    let mut parts = Vec::new();
    if shell_str == "default" {
        parts.push("sh".to_string());
        parts.push("-c".to_string());
    } else {
        let split_parts = parse_shell_words(shell_str);
        parts.extend(split_parts);
        parts.push("-c".to_string());
    }

    // Calibrate shell spawning time by running empty command multiple times
    let mut total_time = 0.0;
    let runs = 10;
    for _ in 0..runs {
        let (res, exit_code) = run_raw(&parts, "", None, Stdio::null(), Stdio::null(), Stdio::null());
        if exit_code != 0 {
            eprintln!("Error: Could not measure shell execution time. Make sure you can run '{} -c \"\"'.", parts[0]);
            std::process::exit(1);
        }
        total_time += res.time_sec;
    }

    let mean_time = total_time / (runs as f64);

    ShellInfo {
        enabled: true,
        cmd_parts: parts,
        mean_time,
    }
}

pub fn run_aux_command(shell: &ShellInfo, cmd: &str, kind: &str) {
    let (res, exit_code) = if shell.enabled {
        run_raw(&shell.cmd_parts, cmd, None, Stdio::null(), Stdio::null(), Stdio::null())
    } else {
        let parts = parse_shell_words(cmd);
        if parts.is_empty() {
            return;
        }
        let exec = &parts[0];
        let args = &parts[1..];
        run_exec_raw(exec, args, None, Stdio::null(), Stdio::null(), Stdio::null())
    };

    if exit_code != 0 {
        eprintln!("Error: The {} command terminated with a non-zero exit code. Append ' || true' to the command if you are sure that this can be ignored.", kind);
        std::process::exit(1);
    }
}

pub fn run_benchmark_command(
    shell: &ShellInfo,
    task: &BenchmarkTask,
    opts: &Opts,
    iteration: &str,
    is_first_run: bool,
) -> RunResult {
    let stdin_io = get_stdin(opts.input.as_deref());
    let (stdout_io, stderr_io) = get_stdout_stderr(opts, task.output.as_deref());

    let (mut raw_res, exit_code, terminated_by_signal) = if shell.enabled {
        run_raw_full(&shell.cmd_parts, &task.substituted_cmd, Some(iteration), stdin_io, stdout_io, stderr_io)
    } else {
        let parts = parse_shell_words(&task.substituted_cmd);
        if parts.is_empty() {
            eprintln!("Error: Empty command");
            std::process::exit(1);
        }
        let exec = &parts[0];
        let args = &parts[1..];
        run_exec_raw_full(exec, args, Some(iteration), stdin_io, stdout_io, stderr_io)
    };

    if shell.enabled {
        raw_res.time_sec = (raw_res.time_sec - shell.mean_time).max(0.0);
    }

    if exit_code != 0 {
        let should_ignore = match &opts.ignore_failure {
            IgnoreFailure::None => false,
            IgnoreFailure::All => true,
            IgnoreFailure::Specific(codes) => codes.contains(&exit_code),
        };

        if !should_ignore {
            if terminated_by_signal {
                if is_first_run {
                    eprintln!("Error: The process has been terminated by a signal in the first benchmark run. Use the '-i'/'--ignore-failure' option if you want to ignore this. Alternatively, use the '--show-output' option to debug what went wrong.");
                } else {
                    eprintln!("Error: The process has been terminated by a signal. Use the '-i'/'--ignore-failure' option if you want to ignore this. Alternatively, use the '--show-output' option to debug what went wrong.");
                }
            } else {
                if is_first_run {
                    eprintln!("Error: Command terminated with non-zero exit code {} in the first benchmark run. Use the '-i'/'--ignore-failure' option if you want to ignore this. Alternatively, use the '--show-output' option to debug what went wrong.", exit_code);
                } else {
                    eprintln!("Error: Command terminated with non-zero exit code {}. Use the '-i'/'--ignore-failure' option if you want to ignore this. Alternatively, use the '--show-output' option to debug what went wrong.", exit_code);
                }
            }
            std::process::exit(1);
        }
    }

    raw_res
}

fn get_stdin(input: Option<&str>) -> Stdio {
    match input {
        None | Some("null") => Stdio::null(),
        Some(path) => {
            match File::open(path) {
                Ok(file) => Stdio::from(file),
                Err(_) => {
                    eprintln!("Error: The file '{}' specified as '--input' does not exist", path);
                    std::process::exit(1);
                }
            }
        }
    }
}

fn get_stdout_stderr(opts: &Opts, output: Option<&str>) -> (Stdio, Stdio) {
    if opts.show_output {
        return (Stdio::inherit(), Stdio::inherit());
    }

    match output {
        None | Some("null") => (Stdio::null(), Stdio::null()),
        Some("inherit") => (Stdio::inherit(), Stdio::inherit()),
        Some("pipe") => (Stdio::piped(), Stdio::piped()),
        Some(path) => {
            match OpenOptions::new().create(true).write(true).append(true).open(path) {
                Ok(file) => {
                    let file2 = file.try_clone().unwrap();
                    (Stdio::from(file), Stdio::from(file2))
                }
                Err(e) => {
                    eprintln!("Error: {} (os error {})", e, e.raw_os_error().unwrap_or(2));
                    std::process::exit(1);
                }
            }
        }
    }
}

fn run_raw(
    shell_parts: &[String],
    cmd: &str,
    iter_env: Option<&str>,
    stdin: Stdio,
    stdout: Stdio,
    stderr: Stdio,
) -> (RunResult, i32) {
    let (res, exit_code, _) = run_raw_full(shell_parts, cmd, iter_env, stdin, stdout, stderr);
    (res, exit_code)
}

fn run_raw_full(
    shell_parts: &[String],
    cmd: &str,
    iter_env: Option<&str>,
    stdin: Stdio,
    stdout: Stdio,
    stderr: Stdio,
) -> (RunResult, i32, bool) {
    let mut command = Command::new(&shell_parts[0]);
    if shell_parts.len() > 1 {
        command.args(&shell_parts[1..]);
    }
    command.arg(cmd);

    if let Some(iter) = iter_env {
        command.env("HYPERFINE_ITERATION", iter);
    } else {
        command.env_remove("HYPERFINE_ITERATION");
    }

    command.stdin(stdin).stdout(stdout).stderr(stderr);

    let start = Instant::now();
    let child = match command.spawn() {
        Ok(child) => child,
        Err(e) => {
            eprintln!("Error: Could not spawn process: {}", e);
            std::process::exit(1);
        }
    };

    let pid = child.id() as i32;
    let mut status: i32 = 0;
    let mut rusage: rusage = unsafe { std::mem::zeroed() };

    unsafe {
        wait4(pid, &mut status, 0, &mut rusage);
    }
    let elapsed = start.elapsed().as_secs_f64();

    let user = rusage.ru_utime.tv_sec as f64 + rusage.ru_utime.tv_usec as f64 * 1e-6;
    let sys = rusage.ru_stime.tv_sec as f64 + rusage.ru_stime.tv_usec as f64 * 1e-6;
    let rss = (rusage.ru_maxrss as u64) * 1024;

    let (exit_code, is_sig) = decode_status(status);

    (
        RunResult {
            time_sec: elapsed,
            user_sec: user,
            system_sec: sys,
            max_rss_bytes: rss,
            exit_code,
        },
        exit_code,
        is_sig,
    )
}

fn run_exec_raw(
    exec: &str,
    args: &[String],
    iter_env: Option<&str>,
    stdin: Stdio,
    stdout: Stdio,
    stderr: Stdio,
) -> (RunResult, i32) {
    let (res, exit_code, _) = run_exec_raw_full(exec, args, iter_env, stdin, stdout, stderr);
    (res, exit_code)
}

fn run_exec_raw_full(
    exec: &str,
    args: &[String],
    iter_env: Option<&str>,
    stdin: Stdio,
    stdout: Stdio,
    stderr: Stdio,
) -> (RunResult, i32, bool) {
    let mut command = Command::new(exec);
    command.args(args);

    if let Some(iter) = iter_env {
        command.env("HYPERFINE_ITERATION", iter);
    } else {
        command.env_remove("HYPERFINE_ITERATION");
    }

    command.stdin(stdin).stdout(stdout).stderr(stderr);

    let start = Instant::now();
    let child = match command.spawn() {
        Ok(child) => child,
        Err(e) => {
            eprintln!("Error: Could not spawn process '{}': {}", exec, e);
            std::process::exit(1);
        }
    };

    let pid = child.id() as i32;
    let mut status: i32 = 0;
    let mut rusage: rusage = unsafe { std::mem::zeroed() };

    unsafe {
        wait4(pid, &mut status, 0, &mut rusage);
    }
    let elapsed = start.elapsed().as_secs_f64();

    let user = rusage.ru_utime.tv_sec as f64 + rusage.ru_utime.tv_usec as f64 * 1e-6;
    let sys = rusage.ru_stime.tv_sec as f64 + rusage.ru_stime.tv_usec as f64 * 1e-6;
    let rss = (rusage.ru_maxrss as u64) * 1024;

    let (exit_code, is_sig) = decode_status(status);

    (
        RunResult {
            time_sec: elapsed,
            user_sec: user,
            system_sec: sys,
            max_rss_bytes: rss,
            exit_code,
        },
        exit_code,
        is_sig,
    )
}

fn decode_status(status: i32) -> (i32, bool) {
    let sig = status & 0x7f;
    if sig == 0 {
        let code = (status >> 8) & 0xff;
        (code, false)
    } else {
        (128 + sig, true)
    }
}

pub fn parse_shell_words(s: &str) -> Vec<String> {
    let mut words = Vec::new();
    let mut current = String::new();
    let mut in_single_quote = false;
    let mut in_double_quote = false;
    let mut chars = s.chars().peekable();

    while let Some(c) = chars.next() {
        match c {
            '\'' if !in_double_quote => {
                in_single_quote = !in_single_quote;
            }
            '"' if !in_single_quote => {
                in_double_quote = !in_double_quote;
            }
            '\\' if !in_single_quote => {
                if let Some(next_c) = chars.next() {
                    current.push(next_c);
                }
            }
            c if c.is_whitespace() && !in_single_quote && !in_double_quote => {
                if !current.is_empty() {
                    words.push(current.clone());
                    current.clear();
                }
            }
            _ => {
                current.push(c);
            }
        }
    }

    if !current.is_empty() {
        words.push(current);
    }

    words
}
