        let memory_usage_bytes: Vec<u64> = runs.iter().map(|r| r.max_rss_bytes).collect();
        let exit_codes: Vec<i32> = runs.iter().map(|r| r.exit_code).collect();
        let has_non_zero_exit = exit_codes.iter().any(|&c| c != 0);

        let count = times.len();
        let sum_time: f64 = times.iter().sum();
        let mean = if count > 0 { sum_time / (count as f64) } else { 0.0 };

        let sum_user: f64 = runs.iter().map(|r| r.user_sec).sum();
        let user_mean = if count > 0 { sum_user / (count as f64) } else { 0.0 };

        let sum_sys: f64 = runs.iter().map(|r| r.system_sec).sum();
        let system_mean = if count > 0 { sum_sys / (count as f64) } else { 0.0 };

        let min = times.iter().cloned().fold(f64::INFINITY, f64::min);
        let max = times.iter().cloned().fold(f64::NEG_INFINITY, f64::max);

        let stddev = if count > 1 {
            let variance = times.iter().map(|&t| (t - mean).powi(2)).sum::<f64>() / ((count - 1) as f64);
            Some(variance.sqrt())
        } else {
            None
        };

        let mut sorted_times = times.clone();
        sorted_times.sort_by(|a, b| a.partial_cmp(b).unwrap());

        let median = if count == 0 {
            0.0
        } else if count % 2 == 1 {
            sorted_times[count / 2]
        } else {
            (sorted_times[count / 2 - 1] + sorted_times[count / 2]) / 2.0
        };

        BenchmarkStats {
            task_index,
            command_display,
            substituted_cmd,
            times,
            memory_usage_bytes,
            exit_codes,
            mean,
            stddev,
            median,
            min: if min.is_infinite() { 0.0 } else { min },
            max: if max.is_infinite() { 0.0 } else { max },
            user_mean,
            system_mean,
            has_non_zero_exit,
            parameters,
        }
    }
}

pub fn check_first_run_outlier(times: &[f64]) -> Option<f64> {
    if times.len() < 3 {
        return None;
    }

    let first = times[0];
    let rest = &times[1..];
    let rest_count = rest.len() as f64;
    let rest_mean = rest.iter().sum::<f64>() / rest_count;
    let rest_variance = rest.iter().map(|&t| (t - rest_mean).powi(2)).sum::<f64>() / (rest_count - 1.0);
    let rest_stddev = rest_variance.sqrt();

    if first > rest_mean + 3.0 * rest_stddev && first > 1.5 * rest_mean {
        Some(first)
    } else {
        None
    }
}

pub fn check_statistical_outliers(times: &[f64], mean: f64, stddev: Option<f64>) -> bool {
    if times.len() < 4 {
        return false;
    }
    if let Some(s) = stddev {
        if s == 0.0 {
            return false;
        }
        for &t in times {
            if (t - mean).abs() > 3.0 * s {
                return true;
            }
        }
    }
    false
}
