{"command":"cat <<'EOF' > src/format.rs
use crate::stats::BenchmarkStats;
use std::io::IsTerminal;

#[derive(Debug, Clone, Copy, PartialEq)]
pub enum TimeUnit {
    Microsecond,
    Millisecond,
    Second,
}

impl TimeUnit {
    pub fn from_str(s: &str) -> Option<Self> {
        match s {
            "microsecond" => Some(TimeUnit::Microsecond),
            "millisecond" => Some(TimeUnit::Millisecond),
            "second" => Some(TimeUnit::Second),
            _ => None,
        }
    }

    pub fn auto(val_sec: f64) -> Self {
        if val_sec < 0.001 {
            TimeUnit::Microsecond
        } else if val_sec < 1.0 {
            TimeUnit::Millisecond
        } else {
            TimeUnit::Second
        }
    }

    pub fn label(&self) -> &'static str {
        match self {
            TimeUnit::Microsecond => "µs",
            TimeUnit::Millisecond => "ms",
            TimeUnit::Second => "s",
        }
    }

    pub fn format(&self, val_sec: f64) -> String {
        match self {
            TimeUnit::Microsecond => format!("{:.1} µs", val_sec * 1e6),
            TimeUnit::Millisecond => format!("{:.1} ms", val_sec * 1e3),
            TimeUnit::Second => format!("{:.3} s", val_sec),
        }
    }

    pub fn format_value_only(&self, val_sec: f64) -> String {
        match self {
            TimeUnit::Microsecond => format!("{:.1}", val_sec * 1e6),
            TimeUnit::Millisecond => format!("{:.1}", val_sec * 1e3),
            TimeUnit::Second => format!("{:.3}", val_sec),
        }
    }
}

pub struct TerminalStyle {
    pub use_color: bool,
    pub is_none: bool,
}

impl TerminalStyle {
    pub fn new(style_opt: &str) -> Self {
        let is_tty = std::io::stdout().is_terminal();
        match style_opt {
            "none" => TerminalStyle { use_color: false, is_none: true },
            "basic" | "nocolor" => TerminalStyle { use_color: false, is_none: false },
            "color" | "full" => TerminalStyle { use_color: true, is_none: false },
            "auto" | _ => TerminalStyle { use_color: is_tty, is_none: false },
        }
    }

    pub fn bold(&self, s: &str) -> String {
        if self.use_color { format!("\x1b[1m{}\x1b[0m", s) } else { s.to_string() }
    }

    pub fn bold_green(&self, s: &str) -> String {
        if self.use_color { format!("\x1b[1;32m{}\x1b[0m", s) } else { s.to_string() }
    }

    pub fn green(&self, s: &str) -> String {
        if self.use_color { format!("\x1b[32m{}\x1b[0m", s) } else { s.to_string() }
    }

    pub fn blue(&self, s: &str) -> String {
        if self.use_color { format!("\x1b[34m{}\x1b[0m", s) } else { s.to_string() }
    }

    pub fn cyan(&self, s: &str) -> String {
        if self.use_color { format!("\x1b[36m{}\x1b[0m", s) } else { s.to_string() }
    }

    pub fn magenta(&self, s: &str) -> String {
        if self.use_color { format!("\x1b[35m{}\x1b[0m", s) } else { s.to_string() }
    }

    pub fn dim(&self, s: &str) -> String {
        if self.use_color { format!("\x1b[2m{}\x1b[0m", s) } else { s.to_string() }
    }
}

pub fn print_benchmark_results(
    stats: &BenchmarkStats,
    style: &TerminalStyle,
    forced_unit: Option<TimeUnit>,
    warnings: &[String],
) {
    if style.is_none {
        return;
    }

    let b_num = stats.task_index + 1;
    println!("{} {}: {}", style.bold("Benchmark"), style.bold(&b_num.to_string()), stats.command_display);

    for warning in warnings {
        println!("  Warning: {}", warning);
    }

    let unit = forced_unit.unwrap_or_else(|| TimeUnit::auto(stats.mean));

    let run_count = stats.times.len();

    let user_str = style.blue(&unit.format(stats.user_mean));
    let sys_str = style.blue(&unit.format(stats.system_mean));

    if run_count > 1 {
        let mean_str = style.bold_green(&unit.format(stats.mean));
        let stddev_str = if let Some(s) = stats.stddev {
            style.green(&format!("{:>8}", unit.format(s)))
        } else {
            String::new()
        };

        let mean_label = style.bold_green("mean");
        let sigma_label = style.green("σ");

        println!(
            "  Time ({}\u{00a0}±\u{00a0}{}):     {} ± {}    [User: {}, System: {}]",
            mean_label, sigma_label, mean_str, stddev_str, user_str, sys_str
        );

        let min_label = style.cyan("min");
        let max_label = style.magenta("max");
        let min_str = style.cyan(&unit.format(stats.min));
        let max_str = style.magenta(&unit.format(stats.max));
        let runs_str = style.dim(&format!("{} runs", run_count));

        println!(
            "  Range ({} … {}):   {} … {}    {}",
            min_label, max_label, min_str, max_str, runs_str
        );
    } else {
        let abs_label = style.bold_green("abs");
        let abs_str = style.bold_green(&unit.format(stats.mean));

        println!(
            "  Time ({} ≡):        {}               [User: {}, System: {}]",
            abs_label, abs_str, user_str, sys_str
        );
    }

    println!();
}

pub fn print_summary(
    all_stats: &[BenchmarkStats],
    style: &TerminalStyle,
    sort_method: &str,
    reference_idx: Option<usize>,
) {
    if style.is_none || all_stats.len() <= 1 {
        return;
    }

    // Check if any benchmark time is 0.0
    if all_stats.iter().any(|s| s.mean == 0.0) {
        println!("Note: The benchmark comparison could not be computed as some benchmark times are zero. This could be caused by background interference during the initial calibration phase of hyperfine, in combination with very fast commands (faster than a few milliseconds). Try to re-run the benchmark on a quiet system. If you did not do so already, try the --shell=none/-N option. If it does not help either, you command is most likely too fast to be accurately benchmarked by hyperfine.");
        return;
    }

    // Determine baseline (reference or fastest)
    let ref_stats = if let Some(idx) = reference_idx {
        &all_stats[idx]
    } else {
        all_stats.iter().min_by(|a, b| a.mean.partial_cmp(&b.mean).unwrap()).unwrap()
    };

    if sort_method == "command" {
        println!("{}", style.bold("Relative speed comparison"));
        for s in all_stats {
            let ratio = s.mean / ref_stats.mean;
            let ratio_std = match (s.stddev, ref_stats.stddev) {
                (Some(s1), Some(s2)) => {
                    let cv1 = s1 / s.mean;
                    let cv2 = s2 / ref_stats.mean;
                    Some(ratio * (cv1 * cv1 + cv2 * cv2).sqrt())
                }
                _ => None,
            };

            let cmd_str = &s.command_display;

            if (ratio - 1.0).abs() < 1e-6 {
                let r_str = style.bold_green(&format!("{:>10.2}", ratio));
                println!("  {}          {}", r_str, cmd_str);
            } else {
                let r_str = style.bold_green(&format!("{:>10.2}", ratio));
                if let Some(r_std) = ratio_std {
                    let r_std_str = style.green(&format!("{:.2}", r_std));
                    println!("  {} ±  {}  {}", r_str, r_std_str, cmd_str);
                } else {
                    println!("  {}          {}", r_str, cmd_str);
                }
            }
        }
    } else {
        // "mean-time" or "auto"
        println!("{}", style.bold("Summary"));
        println!("  {} ran", style.cyan(&ref_stats.command_display));

        let mut other_stats: Vec<&BenchmarkStats> = all_stats.iter().filter(|s| s.task_index != ref_stats.task_index).collect();
        other_stats.sort_by(|a, b| a.mean.partial_cmp(&b.mean).unwrap());

        for s in other_stats {
            let is_slower = s.mean > ref_stats.mean;
            let ratio = if is_slower {
                s.mean / ref_stats.mean
            } else {
                ref_stats.mean / s.mean
            };

            let ratio_std = match (s.stddev, ref_stats.stddev) {
                (Some(s1), Some(s2)) => {
                    let cv1 = s1 / s.mean;
                    let cv2 = s2 / ref_stats.mean;
                    Some(ratio * (cv1 * cv1 + cv2 * cv2).sqrt())
                }
                _ => None,
            };

            let relationship = if is_slower { "faster than" } else { "slower than" };

            let ratio_str = style.bold_green(&format!("{:.2}", ratio));
            let cmd_str = style.magenta(&s.command_display);

            if let Some(r_std) = ratio_std {
                let r_std_str = style.green(&format!("{:.2}", r_std));
                println!("    {} ± {} times {} {}", ratio_str, r_std_str, relationship, cmd_str);
            } else {
                println!("    {} times {} {}", ratio_str, relationship, cmd_str);
            }
        }
    }
}
EOF"}

