{"command":"cat <<'EOF' > src/export.rs
use std::fs::File;
use std::io::Write;
use std::path::Path;
use std::process;
use crate::format::TimeUnit;
use crate::stats::BenchmarkStats;

pub fn export_csv(path: &Path, stats_list: &[BenchmarkStats]) {
    let mut file = match File::create(path) {
        Ok(f) => f,
        Err(e) => {
            eprintln!("Error: Could not create export file '{}': {}", path.display(), e);
            process::exit(1);
        }
    };

    // Collect all parameter keys in order of appearance
    let mut param_keys = Vec::new();
    for s in stats_list {
        for (k, _) in &s.parameters {
            if !param_keys.contains(k) {
                param_keys.push(k.clone());
            }
        }
    }

    let mut header = vec!["command", "mean", "stddev", "median", "user", "system", "min", "max"];
    let param_headers: Vec<String> = param_keys.iter().map(|k| format!("parameter_{}", k)).collect();
    for ph in &param_headers {
        header.push(ph.as_str());
    }

    let _ = writeln!(file, "{}", header.join(","));

    for s in stats_list {
        let stddev_val = s.stddev.unwrap_or(0.0);
        let mut row = vec![
            escape_csv(&s.substituted_cmd),
            format!("{}", s.mean),
            format!("{}", stddev_val),
            format!("{}", s.median),
            format!("{}", s.user_mean),
            format!("{}", s.system_mean),
            format!("{}", s.min),
            format!("{}", s.max),
        ];

        for k in &param_keys {
            let val = s.parameters.iter().find(|(pk, _)| pk == k).map(|(_, v)| v.as_str()).unwrap_or("");
            row.push(escape_csv(val));
        }

        let _ = writeln!(file, "{}", row.join(","));
    }
}

fn escape_csv(s: &str) -> String {
    if s.contains(',') || s.contains('"') || s.contains('\n') {
        format!("\"{}\"", s.replace('"', "\"\""))
    } else {
        s.to_string()
    }
}

pub fn export_json(path: &Path, stats_list: &[BenchmarkStats]) {
    let mut file = match File::create(path) {
        Ok(f) => f,
        Err(e) => {
            eprintln!("Error: Could not create export file '{}': {}", path.display(), e);
            process::exit(1);
        }
    };

    let _ = writeln!(file, "{{\n  \"results\": [");

    for (i, s) in stats_list.iter().enumerate() {
        let is_last = i == stats_list.len() - 1;

        let stddev_str = match s.stddev {
            Some(val) => format!("{}", val),
            None => "null".to_string(),
        };

        let times_str = s.times.iter().map(|t| format!("{}", t)).collect::<Vec<_>>().join(",\n        ");
        let rss_str = s.memory_usage_bytes.iter().map(|m| format!("{}", m)).collect::<Vec<_>>().join(",\n        ");
        let codes_str = s.exit_codes.iter().map(|c| format!("{}", c)).collect::<Vec<_>>().join(",\n        ");

        let mut entry = format!(
            "    {{\n      \"command\": {},\n      \"mean\": {},\n      \"stddev\": {},\n      \"median\": {},\n      \"user\": {},\n      \"system\": {},\n      \"min\": {},\n      \"max\": {},\n      \"times\": [\n        {}\n      ],\n      \"memory_usage_byte\": [\n        {}\n      ],\n      \"exit_codes\": [\n        {}\n      ]",
            json_escape(&s.substituted_cmd),
            s.mean,
            stddev_str,
            s.median,
            s.user_mean,
            s.system_mean,
            s.min,
            s.max,
            times_str,
            rss_str,
            codes_str
        );

        if !s.parameters.is_empty() {
            let param_entries = s.parameters.iter().map(|(k, v)| format!("        {}: {}", json_escape(k), json_escape(v))).collect::<Vec<_>>().join(",\n");
            entry.push_str(&format!(",\n      \"parameters\": {{\n{}\n      }}", param_entries));
        }

        if is_last {
            let _ = writeln!(file, "{}\n    }}", entry);
        } else {
            let _ = writeln!(file, "{}\n    }},", entry);
        }
    }

    let _ = writeln!(file, "  ]\n}}");
}

fn json_escape(s: &str) -> String {
    let mut out = String::from("\"");
    for c in s.chars() {
        match c {
            '"' => out.push_str("\\\""),
            '\\' => out.push_str("\\\\"),
            '\n' => out.push_str("\\n"),
            '\r' => out.push_str("\\r"),
            '\t' => out.push_str("\\t"),
            _ => out.push(c),
        }
    }
    out.push('"');
    out
}

pub fn export_markup(
    path: &Path,
    stats_list: &[BenchmarkStats],
    format_type: &str, // "markdown", "asciidoc", "orgmode"
    sort_method: &str,
    forced_unit: Option<TimeUnit>,
    reference_idx: Option<usize>,
) {
    let mut file = match File::create(path) {
        Ok(f) => f,
        Err(e) => {
            eprintln!("Error: Could not create export file '{}': {}", path.display(), e);
            process::exit(1);
        }
    };

    // Sort entries if sort_method is "mean-time"
    let mut sorted_stats: Vec<&BenchmarkStats> = stats_list.iter().collect();
    if sort_method == "mean-time" {
        sorted_stats.sort_by(|a, b| a.mean.partial_cmp(&b.mean).unwrap());
    }

    // Determine unit
    let unit = forced_unit.unwrap_or_else(|| {
        let min_mean = stats_list.iter().map(|s| s.mean).fold(f64::INFINITY, f64::min);
        TimeUnit::auto(if min_mean.is_infinite() { 1.0 } else { min_mean })
    });

    let unit_label = unit.label();

    // Determine reference for relative calculations
    let ref_stats = if let Some(idx) = reference_idx {
        &stats_list[idx]
    } else {
        stats_list.iter().min_by(|a, b| a.mean.partial_cmp(&b.mean).unwrap()).unwrap()
    };

    match format_type {
        "markdown" => {
            let _ = writeln!(file, "| Command | Mean [{}] | Min [{}] | Max [{}] | Relative |", unit_label, unit_label, unit_label);
            let _ = writeln!(file, "|:---|---:|---:|---:|---:|");

            for s in sorted_stats {
                let mean_str = if let Some(std) = s.stddev {
                    format!("{} ± {}", unit.format_value_only(s.mean), unit.format_value_only(std))
                } else {
                    unit.format_value_only(s.mean)
                };

                let rel_str = get_relative_str(s, ref_stats);
                let cmd_str = format!("`{}`", s.command_display);

                let _ = writeln!(
                    file,
                    "| {} | {} | {} | {} | {} |",
                    cmd_str,
                    mean_str,
                    unit.format_value_only(s.min),
                    unit.format_value_only(s.max),
                    rel_str
                );
            }
        }
        "asciidoc" => {
            let _ = writeln!(file, "[cols=\"<,>,>,>,>\"]");
            let _ = writeln!(file, "|===");
            let _ = writeln!(file, "| Command \n| Mean [{}] \n| Min [{}] \n| Max [{}] \n| Relative \n", unit_label, unit_label, unit_label);

            for s in sorted_stats {
                let mean_str = if let Some(std) = s.stddev {
                    format!("{} ± {}", unit.format_value_only(s.mean), unit.format_value_only(std))
                } else {
                    unit.format_value_only(s.mean)
                };

                let rel_str = get_relative_str(s, ref_stats);
                let cmd_str = format!("`{}`", s.command_display);

                let _ = writeln!(
                    file,
                    "| {} \n| {} \n| {} \n| {} \n| {} \n",
                    cmd_str,
                    mean_str,
                    unit.format_value_only(s.min),
                    unit.format_value_only(s.max),
                    rel_str
                );
            }

            let _ = writeln!(file, "|===");
        }
        "orgmode" => {
            let _ = writeln!(file, "| Command  |  Mean [{}] |  Min [{}] |  Max [{}] |  Relative |", unit_label, unit_label, unit_label);
            let _ = writeln!(file, "|--+--+--+--+--|");

            for s in sorted_stats {
                let mean_str = if let Some(std) = s.stddev {
                    format!("{} ± {}", unit.format_value_only(s.mean), unit.format_value_only(std))
                } else {
                    unit.format_value_only(s.mean)
                };

                let rel_str = get_relative_str(s, ref_stats);
                let cmd_str = format!("={}", s.command_display) + "=";

                let _ = writeln!(
                    file,
                    "| {}  |  {} |  {} |  {} |  {} |",
                    cmd_str,
                    mean_str,
                    unit.format_value_only(s.min),
                    unit.format_value_only(s.max),
                    rel_str
                );
            }
        }
        _ => {}
    }
}

fn get_relative_str(s: &BenchmarkStats, ref_stats: &BenchmarkStats) -> String {
    if ref_stats.mean == 0.0 {
        return "inf".to_string();
    }

    let ratio = s.mean / ref_stats.mean;

    if (ratio - 1.0).abs() < 1e-6 && s.task_index == ref_stats.task_index {
        return "1.00".to_string();
    }

    let ratio_std = match (s.stddev, ref_stats.stddev) {
        (Some(s1), Some(s2)) => {
            let cv1 = s1 / s.mean;
            let cv2 = s2 / ref_stats.mean;
            Some(ratio * (cv1 * cv1 + cv2 * cv2).sqrt())
        }
        _ => None,
    };

    if let Some(r_std) = ratio_std {
        format!("{:.2} ± {:.2}", ratio, r_std)
    } else {
        format!("{:.2}", ratio)
    }
}
