pub fn export_markup(
    path: &Path,
    stats_list: &[BenchmarkStats],
    format_type: &str, // "markdown", "asciidoc", "orgmode"
    sort_method: &str,
    forced_unit: Option<TimeUnit>,
    reference_idx: Option<usize>,
) {
    let mut file = match File::create(path) {
        Ok(f) => f,
        Err(e) => {
            eprintln!("Error: Could not create export file '{}': {}", path.display(), e);
            process::exit(1);
        }
    };

    // Sort entries if sort_method is "mean-time"
    let mut sorted_stats: Vec<&BenchmarkStats> = stats_list.iter().collect();
    if sort_method == "mean-time" {
        sorted_stats.sort_by(|a, b| a.mean.partial_cmp(&b.mean).unwrap());
    }

    // Determine unit
    let unit = forced_unit.unwrap_or_else(|| {
        let min_mean = stats_list.iter().map(|s| s.mean).fold(f64::INFINITY, f64::min);
        TimeUnit::auto(if min_mean.is_infinite() { 1.0 } else { min_mean })
    });

    let unit_label = unit.label();

    // Determine reference for relative calculations
    let ref_stats = if let Some(idx) = reference_idx {
        &stats_list[idx]
    } else {
        stats_list.iter().min_by(|a, b| a.mean.partial_cmp(&b.mean).unwrap()).unwrap()
    };

    match format_type {
        "markdown" => {
            let _ = writeln!(file, "| Command | Mean [{}] | Min [{}] | Max [{}] | Relative |", unit_label, unit_label, unit_label);
            let _ = writeln!(file, "|:---|---:|---:|---:|---:|");

            for s in sorted_stats {
                let mean_str = if let Some(std) = s.stddev {
                    format!("{} ± {}", unit.format_value_only(s.mean), unit.format_value_only(std))
                } else {
                    unit.format_value_only(s.mean)
                };

                let rel_str = get_relative_str(s, ref_stats);
                let cmd_str = format!("`{}`", s.command_display);

                let _ = writeln!(
                    file,
                    "| {} | {} | {} | {} | {} |",
                    cmd_str,
                    mean_str,
                    unit.format_value_only(s.min),
                    unit.format_value_only(s.max),
                    rel_str
                );
            }
        }
        "asciidoc" => {
            let _ = writeln!(file, "[cols=\"<,>,>,>,>\"]");
            let _ = writeln!(file, "|===");
            let _ = writeln!(file, "| Command \n| Mean [{}] \n| Min [{}] \n| Max [{}] \n| Relative \n", unit_label, unit_label, unit_label);

            for s in sorted_stats {
                let mean_str = if let Some(std) = s.stddev {
                    format!("{} ± {}", unit.format_value_only(s.mean), unit.format_value_only(std))
                } else {
                    unit.format_value_only(s.mean)
                };

                let rel_str = get_relative_str(s, ref_stats);
                let cmd_str = format!("`{}`", s.command_display);

                let _ = writeln!(
                    file,
                    "| {} \n| {} \n| {} \n| {} \n| {} \n",
                    cmd_str,
                    mean_str,
                    unit.format_value_only(s.min),
                    unit.format_value_only(s.max),
                    rel_str
                );
            }

            let _ = writeln!(file, "|===");
        }
        "orgmode" => {
            let _ = writeln!(file, "| Command  |  Mean [{}] |  Min [{}] |  Max [{}] |  Relative |", unit_label, unit_label, unit_label);
            let _ = writeln!(file, "|--+--+--+--+--|");

            for s in sorted_stats {
                let mean_str = if let Some(std) = s.stddev {
                    format!("{} ± {}", unit.format_value_only(s.mean), unit.format_value_only(std))
                } else {
                    unit.format_value_only(s.mean)
                };

                let rel_str = get_relative_str(s, ref_stats);
                let cmd_str = format!("={}", s.command_display) + "=";

                let _ = writeln!(
                    file,
                    "| {}  |  {} |  {} |  {} |  {} |",
                    cmd_str,
                    mean_str,
                    unit.format_value_only(s.min),
                    unit.format_value_only(s.max),
                    rel_str
                );
            }
        }
        _ => {}
    }
}

fn get_relative_str(s: &BenchmarkStats, ref_stats: &BenchmarkStats) -> String {
    if ref_stats.mean == 0.0 {
        return "inf".to_string();
    }

    let ratio = s.mean / ref_stats.mean;

    if (ratio - 1.0).abs() < 1e-6 && s.task_index == ref_stats.task_index {
        return "1.00".to_string();
    }

    let ratio_std = match (s.stddev, ref_stats.stddev) {
        (Some(s1), Some(s2)) => {
            let cv1 = s1 / s.mean;
            let cv2 = s2 / ref_stats.mean;
            Some(ratio * (cv1 * cv1 + cv2 * cv2).sqrt())
        }
        _ => None,
    };

    if let Some(r_std) = ratio_std {
        format!("{:.2} ± {:.2}", ratio, r_std)
    } else {
        format!("{:.2}", ratio)
    }
}
