{"command":"cat <<'EOF' > src/cli.rs
use std::path::PathBuf;
use std::process;

#[derive(Debug, Clone)]
pub struct ParameterScanOpts {
    pub var: String,
    pub min: String,
    pub max: String,
}

#[derive(Debug, Clone)]
pub struct ParameterListOpts {
    pub var: String,
