mod cli;
mod parameter;
mod runner;
mod stats;
mod format;
mod export;

use std::process;
use std::fs::File;
use stats::BenchmarkStats;

fn main() {
    let opts = cli::parse_args();

    // Check for conflicting runs requirement
    if opts.runs.is_none() {
        if let Some(max_r) = opts.max_runs {
            if opts.min_runs > max_r {
                eprintln!("Error: Conflicting requirements for the number of runs (empty range, min is larger than max)");
                process::exit(1);
            }
        }
    }

    // Verify input file path upfront
    if let Some(path) = &opts.input {
        if path != "null" {
            if File::open(path).is_err() {
                eprintln!("Error: The file '{}' specified as '--input' does not exist", path);
                process::exit(1);
            }
        }
    }

    // Verify export file paths upfront
    validate_export_path(opts.export_csv.as_deref());
    validate_export_path(opts.export_json.as_deref());
    validate_export_path(opts.export_markdown.as_deref());
    validate_export_path(opts.export_asciidoc.as_deref());
    validate_export_path(opts.export_orgmode.as_deref());

    let shell = runner::setup_shell(&opts);
    let tasks = parameter::generate_tasks(&opts);

    if tasks.is_empty() {
        process::exit(0);
    }

    let ref_idx = tasks.iter().position(|t| t.is_reference);
    let style = format::TerminalStyle::new(&opts.style);
    let forced_unit = opts.time_unit.as_deref().and_then(format::TimeUnit::from_str);

    let mut all_stats = Vec::new();

    for (i, task) in tasks.iter().enumerate() {
        format::print_benchmark_header(i + 1, &task.display_name, &style);

        if let Some(setup_cmd) = &task.setup {
            runner::run_aux_command(&shell, setup_cmd, "setup");
        }

        if opts.warmup > 0 {
            for w in 0..opts.warmup {
                if let Some(prep_cmd) = &task.prepare {
                    runner::run_aux_command(&shell, prep_cmd, "preparation");
                }

                let iter = format!("warmup-{}", w);
                runner::run_benchmark_command(&shell, task, &opts, &iter, false);

                if let Some(conc_cmd) = &task.conclude {
                    runner::run_aux_command(&shell, conc_cmd, "conclusion");
                }
            }
        }

        let mut runs = Vec::new();

        if let Some(fixed_runs) = opts.runs {
            for k in 0..fixed_runs {
                if let Some(prep_cmd) = &task.prepare {
                    runner::run_aux_command(&shell, prep_cmd, "preparation");
                }

                let iter = format!("{}", k);
                let res = runner::run_benchmark_command(&shell, task, &opts, &iter, k == 0);
                runs.push(res);

                if let Some(conc_cmd) = &task.conclude {
                    runner::run_aux_command(&shell, conc_cmd, "conclusion");
                }
            }
        } else {
            if let Some(prep_cmd) = &task.prepare {
                runner::run_aux_command(&shell, prep_cmd, "preparation");
            }

            let first_res = runner::run_benchmark_command(&shell, task, &opts, "0", true);
            let first_time = first_res.time_sec;
            runs.push(first_res);

            if let Some(conc_cmd) = &task.conclude {
                runner::run_aux_command(&shell, conc_cmd, "conclusion");
            }

            let min_target = opts.min_runs;
            let needed_runs = if first_time > 0.0 {
                (3.0 / first_time).ceil() as u64
            } else {
                min_target
            };

            let mut target_runs = needed_runs.max(min_target);
            if let Some(max_r) = opts.max_runs {
                target_runs = target_runs.min(max_r);
            }
            target_runs = target_runs.max(1);

            for k in 1..target_runs {
                if let Some(prep_cmd) = &task.prepare {
                    runner::run_aux_command(&shell, prep_cmd, "preparation");
                }

                let iter = format!("{}", k);
                let res = runner::run_benchmark_command(&shell, task, &opts, &iter, false);
                runs.push(res);

                if let Some(conc_cmd) = &task.conclude {
                    runner::run_aux_command(&shell, conc_cmd, "conclusion");
                }
            }
        }

        let task_stats = BenchmarkStats::calculate(
            i,
            task.display_name.clone(),
            task.substituted_cmd.clone(),
            &runs,
            task.parameters.clone(),
        );

        let mut warnings = Vec::new();

        if shell.enabled && task_stats.mean < 0.005 {
            warnings.push("Command took less than 5 ms to complete. Note that the results might be inaccurate because hyperfine can not calibrate the shell startup time much more precise than this limit. You can try to use the `-N`/`--shell=none` option to disable the shell completely.".to_string());
        }

        if task_stats.has_non_zero_exit {
            warnings.push("Ignoring non-zero exit code.".to_string());
        }

        let first_outlier = stats::check_first_run_outlier(&task_stats.times);
        if let Some(first_time) = first_outlier {
            let unit = forced_unit.unwrap_or_else(|| format::TimeUnit::auto(first_time));
            let time_str = unit.format(first_time);
            warnings.push(format!("The first benchmarking run for this command was significantly slower than the rest ({}). This could be caused by (filesystem) caches that were not filled until after the first run. You should consider using the '--warmup' option to fill those caches before the actual benchmark. Alternatively, use the '--prepare' option to clear the caches before each timing run.", time_str));
        } else if stats::check_statistical_outliers(&task_stats.times, task_stats.mean, task_stats.stddev) {
            warnings.push("Statistical outliers were detected. Consider re-running this benchmark on a quiet system without any interferences from other programs. It might help to use the '--warmup' or '--prepare' options.".to_string());
        }

        format::print_benchmark_results(&task_stats, &style, forced_unit, &warnings);

        if let Some(cleanup_cmd) = &task.cleanup {
            runner::run_aux_command(&shell, cleanup_cmd, "cleanup");
        }

        all_stats.push(task_stats);
    }

    format::print_summary(&all_stats, &style, &opts.sort, ref_idx);

    if let Some(path) = &opts.export_csv {
        export::export_csv(path, &all_stats);
    }
    if let Some(path) = &opts.export_json {
        export::export_json(path, &all_stats);
    }
    if let Some(path) = &opts.export_markdown {
        export::export_markup(path, &all_stats, "markdown", &opts.sort, forced_unit, ref_idx);
    }
    if let Some(path) = &opts.export_asciidoc {
        export::export_markup(path, &all_stats, "asciidoc", &opts.sort, forced_unit, ref_idx);
    }
    if let Some(path) = &opts.export_orgmode {
        export::export_markup(path, &all_stats, "orgmode", &opts.sort, forced_unit, ref_idx);
    }
}

fn validate_export_path(path_opt: Option<&std::path::Path>) {
    if let Some(path) = path_opt {
        if let Err(e) = File::create(path) {
            eprintln!("Error: Could not create export file '{}': {}", path.display(), e);
            process::exit(1);
        }
    }
}
EOF"}

